.slick-slider {
  position:relative;
  display:block
}
.slick-list {
  overflow:hidden;
  margin:0;
  padding:0
}
.slick-list:focus {
  outline:none
}
.slick-list.dragging {
  cursor:pointer;
  cursor:hand
}
.slick-slider .slick-list,
.slick-slider .slick-track {
  transform:translateZ(0)
}
.slick-track {
  position:relative;
  left:0;
  top:0;
  display:block;
  margin-left:auto;
  margin-right:auto
}
.slick-track:after,
.slick-track:before {
  content:"";
  display:table
}
.slick-track:after {
  clear:both
}
.slick-loading .slick-track {
  visibility:hidden
